for slug,d in T.items():
  d['slug']=slug
  for k in ('intro1','intro2','sty','proc_lead','bk','det'): d[k]=F(d[k])
  d['steps']=[[F(a),F(b)] for a,b in d['steps']]; d['faqs']=[[F(a),F(b)] for a,b in d['faqs']]
  assert '—' not in json.dumps(d) and '10-year' not in json.dumps(d)
  json.dump(d,open(slug+'.json','w'),ensure_ascii=False,indent=1)
  print(slug,len(d['intro1'].split()),'words big')
